"""Factor data: ``factors.json`` (generated by ``tools/update_factors.py`` from DESNZ and EEA) and ``classes.json``
(defaults per product class, maintained by hand)."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

_DIR = Path(__file__).parent


@lru_cache(maxsize=1)
def factors() -> dict[str, Any]:
    return json.loads((_DIR / "factors.json").read_text(encoding="utf-8"))


@lru_cache(maxsize=1)
def classes() -> dict[str, Any]:
    return json.loads((_DIR / "classes.json").read_text(encoding="utf-8"))


def all_sources() -> dict[str, dict[str, Any]]:
    return {**factors()["sources"], **classes()["sources"]}
